Here is an example: classZipPacket:publicsf::Packet
{
constvoid*onSend(std::size_t&size)override
{
constvoid*srcData=getData();
std::size_tsrcSize=getDataSize();

returnMySuperZipFunction(srcData,srcSize,&size);
}

voidonReceive(constvoid*data,std::size_tsize)override
{
std::size_tdstSize;
constvoid*dstData=MySuperUnzipFunction(data,size,&dstSize);

append(dstData,dstSize);
}
};

//Uselikeregularpackets:
ZipPacketpacket;
packet<<x<<s<<d;
